  async function renderMainWaveform(src){var source=String(src||'');var count=48;if(!source){mainWaveSource='';mainWaveRequest++;paintMainWaveform(new Array(count).fill(0));return}if(source===mainWaveSource)return;mainWaveSource=source;var request=++mainWaveRequest;paintMainWaveform(new Array(count).fill(0));var AudioContextClass=window.AudioContext||window.webkitAudioContext;if(!AudioContextClass)return;var context;try{context=new AudioContextClass();var response=await fetch(source);if(!response.ok)throw new Error('Audio is unavailable');var bytes=await response.arrayBuffer();var buffer=await context.decodeAudioData(bytes.slice(0));if(request!==mainWaveRequest)return;var values=[];for(var index=0;index<count;index++){var from=Math.floor(buffer.length*index/count);var to=Math.max(from+1,Math.floor(buffer.length*(index+1)/count));var sampleStep=Math.max(1,Math.floor((to-from)/180));var energy=0;var peak=0;var samples=0;for(var frame=from;frame<to;frame+=sampleStep){var amplitude=0;for(var channel=0;channel<buffer.numberOfChannels;channel++)amplitude+=Math.abs(buffer.getChannelData(channel)[frame]||0);amplitude/=Math.max(1,buffer.numberOfChannels);energy+=amplitude*amplitude;peak=Math.max(peak,amplitude);samples++}values.push(Math.sqrt(energy/Math.max(1,samples))*.72+peak*.28)}var sorted=values.slice().sort(function(a,b){return a-b});var scale=sorted[Math.floor((sorted.length-1)*.92)]||sorted[sorted.length-1]||1;paintMainWaveform(values.map(function(value){return Math.min(1,value/scale)}))}catch(error){if(request===mainWaveRequest)mainWaveSource=''}finally{if(context)context.close().catch(function(){})}}
  function syncMainWave(){var audio=q('ttsAudio');var wrap=q('waveSeekWrap');var range=q('waveSeek');if(!audio||!wrap||!range)return;var duration=finiteDuration(audio);var current=duration?Math.min(duration,Math.max(0,Number(audio.currentTime)||0)):0;var ratio=duration?current/duration:0;wrap.style.setProperty('--wave-progress',(ratio*100).toFixed(3)+'%');range.value=String(Math.round(ratio*1000));range.disabled=!duration;setText('waveTime',formatTime(current))}
