  async function sendAiChat(){if(aiChatBusy)return;var input=q('aiChatInput');var keepKeyboard=aiChatSendKeepsKeyboard||!!(input&&document.activeElement===input);aiChatSendKeepsKeyboard=false;if(keepKeyboard&&input){input.focus();syncAiChatKeyboardOffset()}var typed=String(input&&input.value||'').trim();var attachment=aiChatAttachment;if(!typed&&!attachment)return;var message=typed||(attachment.isImage?'What is in this image?':'Analyze this attachment.');if(attachment)aiChatMessages.forEach(function(item){if(item&&item.attachment)delete item.attachment});appendAiChatMessage('user',message,false,attachment);clearAiChatAttachment();if(input){input.value='';resizeAiChatInput()}aiChatBusy=true;var send=q('aiChatSend');var attach=q('aiChatAttach');if(send)send.disabled=true;if(attach)attach.disabled=true;showAiThinking();try{var data=await streamAiChat({messages:aiChatMessages.slice(-20)},setAiThinkingState);hideAiThinking();if(data.type==='image_request'){showAiImageGenerating();var imageData=await api('/mini-app/api/image',{prompt:String(data.prompt||message),size:String(data.size||'1024x1024')});hideAiImageGenerating();imageData.prompt=String(data.prompt||message);availableCredits=Math.max(0,Number(imageData.balance)||0);if(imageData.pricing)updateImagePricing(imageData.pricing);setText('balance',availableCredits.toLocaleString('en-US'));appendAiChatImage(imageData)}else{await appendAiChatMessage('assistant',String(data.message||''),true)}}catch(error){hideAiThinking();hideAiImageGenerating();toast(error.message||'Could not reach AI')}finally{aiChatBusy=false;if(send)send.disabled=false;if(attach)attach.disabled=false}}
  
  async function showGeneratedImage(data,prompt){var result=q('imageResult');var archivedId='';if(currentImageRecord&&result&&result.classList.contains('show')){archivedId=currentImageRecord.id;result.classList.add('archiving');await new Promise(function(resolve){setTimeout(resolve,280)});currentImageRecord=null;result.classList.remove('show','archiving');result.setAttribute('aria-hidden','true')}var size=String(data.size||selectedImageSize);var mimeType=String(data.mimeType||'image/jpeg');var record={id:String(Date.now())+'-'+Math.random().toString(36).slice(2,8),src:'data:'+mimeType+';base64,'+data.imageBase64,filename:String(data.filename||'vexa-image.jpg'),prompt:prompt,size:size,historyId:data.historyId?String(data.historyId):'',createdAt:Date.now()};currentImageRecord=record;generatedImageSrc=record.src;generatedImageName=record.filename;var preview=q('imageResultPreview');if(preview)preview.src=record.src;if(result){applyImageResultSize(result,size);void result.offsetWidth;result.classList.add('show','revealing');result.setAttribute('aria-hidden','false');setTimeout(function(){result.classList.remove('revealing');result.scrollIntoView({behavior:'smooth',block:'end'})},100)}await saveImageRecord(record,archivedId)}
